"""POSCAR / CIF to Bradley--Cracknell primitive cells for all 230 space groups.

Numerical symmetry detection: spglib. BC Q/U/t0 and generators: Gui-Bin Liu,
SpaceGroupIrep/getBCsymmetry.py 1.2.9 (GPL-3.0). New parsing, validation,
coordinate transport and exports: Symmetry Lab contributors, GPL-3.0.
Lattice vectors are rows; coordinate transformations act on column vectors.
"""
import ast
from fractions import Fraction
import itertools
import math
import re
import numpy as np
import spglib

_MAX_ATOMS = 20000


def _number(value):
    """CIF uncertainty syntax, fractions and Fortran exponents; never eval."""
    text = str(value).strip()
    if text in ('.', '?', ''):
        raise ValueError('Missing numeric structure value')
    text = re.sub(r'\(\d+\)(?=([eEdD][+-]?\d+)?$)', '', text)
    try:
        result = float(Fraction(text.replace('D', 'e').replace('d', 'e')))
    except (ValueError, ZeroDivisionError) as exc:
        raise ValueError('Invalid structure number: ' + text[:60]) from exc
    if not math.isfinite(result):
        raise ValueError('Structure coordinates must be finite')
    return result


def _wrap(value):
    out = np.asarray(value, dtype=float) % 1.0
    out[np.abs(out - 1) < 1e-12] = 0
    out[np.abs(out) < 1e-12] = 0
    return out


def _validate_cell(lattice, positions, species, metadata=None):
    lattice = np.asarray(lattice, dtype=float)
    positions = np.asarray(positions, dtype=float)
    if lattice.shape != (3, 3) or not np.isfinite(lattice).all():
        raise ValueError('Lattice must be a finite 3 by 3 row-vector matrix')
    if abs(np.linalg.det(lattice)) < 1e-10 or np.linalg.cond(lattice) > 1e9:
        raise ValueError('Lattice is singular or too ill-conditioned')
    if positions.ndim != 2 or positions.shape[1] != 3 or not np.isfinite(positions).all():
        raise ValueError('Positions must be a finite N by 3 fractional-coordinate array')
    if not 1 <= len(positions) <= _MAX_ATOMS:
        raise ValueError('Structure must contain 1 to 20000 atoms')
    if len(species) != len(positions) or any(not str(s).strip() for s in species):
        raise ValueError('Provide one nonempty species identifier for each atom')
    return {'lattice': lattice, 'positions': _wrap(positions),
            'species': [str(s).strip() for s in species], 'metadata': metadata or {}}


def parse_poscar(text, species=None):
    lines = str(text).replace('\r', '').splitlines()
    if len(lines) < 8:
        raise ValueError('POSCAR is missing lattice, counts or coordinates')
    scales = [_number(x) for x in lines[1].split()]
    if len(scales) not in (1, 3):
        raise ValueError('POSCAR scale must be one number or three positive factors')
    raw = np.array([[_number(x) for x in line.split()[:3]] for line in lines[2:5]])
    if raw.shape != (3,3) or abs(np.linalg.det(raw)) < 1e-12:
        raise ValueError('Invalid POSCAR lattice')
    if len(scales) == 1:
        if scales[0] == 0:
            raise ValueError('POSCAR scale cannot be zero')
        scale = ((-scales[0] / abs(np.linalg.det(raw))) ** (1/3)
                 if scales[0] < 0 else scales[0])
        factors = np.full(3, scale)
    else:
        if min(scales) <= 0:
            raise ValueError('All three POSCAR scale factors must be positive')
        factors = np.array(scales)
    lattice = raw * factors
    cursor = 5
    tokens = lines[cursor].split()
    warnings = []
    if all(re.fullmatch(r'\d+', x) for x in tokens):
        counts = list(map(int, tokens))
        labels = list(species) if species else ['X' + str(i+1) for i in range(len(counts))]
        if not species:
            warnings.append('VASP 4 file has no species names; distinct anonymous X1, X2, ... types are retained.')
    else:
        labels = tokens
        cursor += 1
        try:
            counts = [int(x) for x in lines[cursor].split()]
        except ValueError as exc:
            raise ValueError('Invalid POSCAR atom counts') from exc
    if len(counts) != len(labels) or any(n < 0 for n in counts) or not 1 <= sum(counts) <= _MAX_ATOMS:
        raise ValueError('POSCAR species/counts disagree or atom count is outside 1..20000')
    if len(set(labels)) != len(labels):
        raise ValueError('POSCAR species identifiers must be distinct; label distinct potentials explicitly')
    cursor += 1
    selective = lines[cursor].strip().lower().startswith('s')
    if selective:
        cursor += 1
    mode = lines[cursor].strip().lower()
    if not mode or mode[0] not in ('d', 'c', 'k'):
        raise ValueError('POSCAR coordinate mode must be Direct or Cartesian')
    cursor += 1
    if len(lines) < cursor + sum(counts):
        raise ValueError('POSCAR contains fewer atom rows than declared')
    coordinates, flags = [], []
    for line in lines[cursor:cursor+sum(counts)]:
        values = line.split()
        if len(values) < 3:
            raise ValueError('Incomplete POSCAR coordinate row')
        coordinates.append([_number(x) for x in values[:3]])
        if selective:
            if len(values) < 6 or any(x.upper() not in ('T','F') for x in values[3:6]):
                raise ValueError('Selective dynamics requires three T/F flags per atom')
            flags.append([x.upper() == 'T' for x in values[3:6]])
    positions = np.asarray(coordinates)
    if mode[0] != 'd':
        positions = (positions * factors) @ np.linalg.inv(lattice)
    if selective:
        warnings.append('Selective-dynamics flags are preserved in input metadata; standardized exports contain geometry only because the basis changes.')
    if any(line.strip() for line in lines[cursor+sum(counts):]):
        warnings.append('Trailing POSCAR velocity/predictor data are preserved as input metadata, not transformed into geometry exports.')
    return _validate_cell(lattice, positions, [label for label, n in zip(labels, counts) for _ in range(n)],
                          {'format':'poscar','title':lines[0], 'warnings':warnings,
                           'selective_dynamics':flags, 'trailing_lines':lines[cursor+sum(counts):]})


def _cif_tokens(text):
    """Tokenize CIF 1.1, retaining quoted/multiline values as indivisible tokens."""
    tokens = []
    lines = str(text).replace('\r', '').splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        if line.startswith(';'):
            value = [line[1:]]
            i += 1
            while i < len(lines) and not lines[i].startswith(';'):
                value.append(lines[i]); i += 1
            if i >= len(lines):
                raise ValueError('Unterminated CIF semicolon text field')
            tokens.append(('\n'.join(value), True))
            i += 1
            continue
        p = 0
        while p < len(line):
            if line[p].isspace(): p += 1; continue
            if line[p] == '#': break
            if line[p] in ('\'', '"'):
                quote, start = line[p], p+1
                p += 1
                while p < len(line) and not (line[p] == quote and (p+1 == len(line) or line[p+1].isspace())):
                    p += 1
                if p == len(line):
                    raise ValueError('Unterminated CIF quoted value')
                tokens.append((line[start:p], True)); p += 1
            else:
                start = p
                while p < len(line) and not line[p].isspace(): p += 1
                tokens.append((line[start:p], False))
        i += 1
    return tokens


def _cif_blocks(text):
    tokens = _cif_tokens(text)
    blocks, block, i = [], None, 0
    def special(token):
        value, quoted = token
        return not quoted and (value.startswith('_') or value.lower().startswith(('data_', 'save_')) or value.lower() in ('loop_', 'stop_', 'global_'))
    while i < len(tokens):
        value, quoted = tokens[i]; low = value.lower()
        if not quoted and low.startswith('data_'):
            block = {'name':value[5:], 'tags':{}, 'loops':[]}; blocks.append(block); i += 1
        elif block is None:
            raise ValueError('CIF must begin with a data_ block')
        elif not quoted and low == 'loop_':
            i += 1; columns = []
            while i < len(tokens) and not tokens[i][1] and tokens[i][0].startswith('_'):
                columns.append(tokens[i][0].lower()); i += 1
            if not columns or len(set(columns)) != len(columns):
                raise ValueError('Invalid CIF loop column names')
            values = []
            while i < len(tokens) and not special(tokens[i]): values.append(tokens[i][0]); i += 1
            if len(values) % len(columns): raise ValueError('CIF loop row has missing fields')
            block['loops'].append((columns, [dict(zip(columns, values[j:j+len(columns)])) for j in range(0,len(values),len(columns))]))
            if i < len(tokens) and tokens[i][0].lower() == 'stop_': i += 1
        elif not quoted and value.startswith('_'):
            if i+1 >= len(tokens) or special(tokens[i+1]): raise ValueError('Missing CIF tag value: ' + value)
            if low in block['tags']: raise ValueError('Repeated CIF tag: '+value)
            block['tags'][low] = tokens[i+1][0]; i += 2
        else:
            raise ValueError('Unsupported CIF control token: '+value[:60])
    return blocks


def _linear_symop(text):
    def walk(node):
        if isinstance(node, ast.Expression): return walk(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int,float)):
            return [Fraction(0),Fraction(0),Fraction(0),Fraction(str(node.value))]
        if isinstance(node, ast.Name) and node.id.lower() in ('x','y','z'):
            out = [Fraction(0)]*4; out['xyz'.index(node.id.lower())] = Fraction(1); return out
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd,ast.USub)):
            return [(-1 if isinstance(node.op,ast.USub) else 1)*v for v in walk(node.operand)]
        if isinstance(node, ast.BinOp):
            left, right = walk(node.left), walk(node.right)
            if isinstance(node.op, (ast.Add,ast.Sub)):
                return [a+(-1 if isinstance(node.op,ast.Sub) else 1)*b for a,b in zip(left,right)]
            if isinstance(node.op, ast.Mult) and (not any(left[:3]) or not any(right[:3])):
                return [v*left[3] for v in right] if not any(left[:3]) else [v*right[3] for v in left]
            if isinstance(node.op, ast.Div) and not any(right[:3]) and right[3]: return [v/right[3] for v in left]
        raise ValueError('CIF symmetry operations must be affine expressions in x,y,z')
    if len(text) > 200: raise ValueError('CIF symmetry operation is too long')
    parts = text.split(',')
    if len(parts) != 3: raise ValueError('CIF symmetry operation needs three coordinates')
    try:
        rows = [walk(ast.parse(part.strip(),mode='eval')) for part in parts]
    except (SyntaxError, RecursionError) as exc: raise ValueError('Invalid CIF symmetry operation') from exc
    rotation = np.array([[float(x) for x in row[:3]] for row in rows])
    if not np.allclose(rotation, np.round(rotation), atol=1e-10) or abs(round(np.linalg.det(rotation))) != 1:
        raise ValueError('CIF symmetry rotation must be integral unimodular')
    return rotation.astype(int), np.array([float(row[3]) for row in rows])


def _periodic_near(delta, lattice, tolerance, bounds):
    """Exact finite integer-translate search for a requested distance threshold.

    If |(delta-n)L| < eps then |delta_i-n_i| < eps |L^-1[:,i]|.
    These reciprocal bounds remain valid for strongly skewed input cells.
    """
    delta = np.asarray(delta,float)
    nearest = delta-np.round(delta)
    if np.any(np.abs(nearest) > bounds+1e-12): return False
    if np.linalg.norm(nearest @ lattice) < tolerance: return True
    if np.all(bounds < .5): return False
    # Cheap witnesses first; a failure here is not used as a negative answer.
    if any(np.linalg.norm((nearest-np.array(offset))@lattice) < tolerance
           for offset in itertools.product((-1,0,1),repeat=3)): return True
    lower=np.ceil(delta-bounds-1e-12).astype(int); upper=np.floor(delta+bounds+1e-12).astype(int)
    count=int(np.prod(upper-lower+1))
    if count > 100000: raise ValueError('Tolerance is too large for this skewed cell; reduce symprec or reduce the input basis')
    return any(np.linalg.norm((delta-np.array(shift)) @ lattice) < tolerance
               for shift in itertools.product(*(range(lo,hi+1) for lo,hi in zip(lower,upper))))


def _deduplicate(positions, species, lattice, tolerance):
    result, labels = [], []
    bounds = tolerance*np.linalg.norm(np.linalg.inv(lattice),axis=0)
    for position, label in zip(_wrap(positions), species):
        found = False
        for old, old_label in zip(result, labels):
            if _periodic_near(position-old,lattice,tolerance,bounds):
                if label != old_label: raise ValueError('Different species occupy the same site; disorder is not supported')
                found = True; break
        if not found: result.append(position); labels.append(label)
    return np.asarray(result), labels


def _cif_operations(tags, loops, warnings):
    keys = ('_space_group_symop_operation_xyz', '_symmetry_equiv_pos_as_xyz', '_space_group_symop.operation_xyz')
    operations = []
    for key in keys:
        if key in tags: operations.append(_linear_symop(tags[key]))
        for columns, rows in loops:
            if key in columns: operations.extend(_linear_symop(row[key]) for row in rows)
        if operations: return operations
    def compact(s): return re.sub(r'[\s_]', '', s).lower()
    hall = tags.get('_space_group_name_hall',tags.get('_symmetry_space_group_name_hall'))
    hm = tags.get('_space_group_name_h-m_alt', tags.get('_symmetry_space_group_name_h-m'))
    it = tags.get('_space_group_it_number',tags.get('_symmetry_int_tables_number'))
    number = _number(it) if it else None
    if number is not None and (not number.is_integer() or not 1 <= number <= 230):
        raise ValueError('CIF International Tables space-group number must be an integer from 1 to 230')
    number = int(number) if number is not None else None
    candidates = []
    for h in range(1,531):
        info = spglib.get_spacegroup_type(h)
        if hall and compact(info.hall_symbol) != compact(hall): continue
        if number and int(info.number) != number: continue
        if hm and compact(hm) not in (compact(info.international_short), compact(info.international_full)): continue
        if hall or number or hm: candidates.append(h)
    if not candidates:
        if hall or number or hm: raise ValueError('CIF declared space-group setting could not be resolved; supply explicit symmetry operations or Hall symbol')
        warnings.append('CIF has no symmetry metadata; atom rows are treated as the complete cell (P1 expansion).')
        return [(np.eye(3,dtype=int),np.zeros(3))]
    if len(candidates) > 1:
        warnings.append('CIF has no unique Hall setting; the first conventional Hall setting was used. Supply explicit symmetry operations/Hall symbol for a different setting.')
    operations = spglib.get_symmetry_from_database(candidates[0])
    return list(zip(operations['rotations'],operations['translations']))


def parse_cif(text, block_name=None, symprec=1e-5):
    blocks = _cif_blocks(text)
    if not blocks: raise ValueError('CIF has no data block')
    if block_name is not None:
        blocks = [b for b in blocks if b['name'] == block_name]
        if len(blocks) != 1: raise ValueError('Requested CIF data block does not exist or is ambiguous')
    else:
        blocks = [b for b in blocks if '_cell_length_a' in b['tags']]
        if len(blocks) != 1: raise ValueError('CIF must have one crystal data block, or select cif_block explicitly')
    block = blocks[0]; tags, loops = block['tags'], block['loops']; warnings = []
    all_keys = set(tags).union(*(set(c) for c,_ in loops))
    if any('magn' in key or 'moment' in key or 'modulation' in key for key in all_keys):
        raise ValueError('Magnetic/modulated CIF data need magnetic structure conversion; ordinary 230-group conversion cannot discard those fields')
    try:
        a,b,c = [_number(tags['_cell_length_'+s]) for s in 'abc']
        alpha,beta,gamma = [math.radians(_number(tags['_cell_angle_'+s])) for s in ('alpha','beta','gamma')]
    except KeyError as exc: raise ValueError('CIF must specify all six cell parameters') from exc
    if min(a,b,c) <= 0 or any(not 0 < angle < math.pi for angle in (alpha,beta,gamma)):
        raise ValueError('Invalid CIF cell lengths or angles')
    cy = (math.cos(alpha)-math.cos(beta)*math.cos(gamma))/math.sin(gamma)
    cz2 = 1-math.cos(beta)**2-cy**2
    if cz2 <= 1e-14: raise ValueError('CIF cell angles do not define a 3D lattice')
    lattice = np.array([[a,0,0],[b*math.cos(gamma),b*math.sin(gamma),0], [c*math.cos(beta),c*cy,c*math.sqrt(cz2)]])
    site_loops = [(columns,rows) for columns,rows in loops if '_atom_site_fract_x' in columns or '_atom_site_cartn_x' in columns]
    if len(site_loops) != 1: raise ValueError('CIF needs one atom-site fractional or Cartesian coordinate loop')
    columns, rows = site_loops[0]
    cartesian = '_atom_site_fract_x' not in columns
    prefix = '_atom_site_cartn_' if cartesian else '_atom_site_fract_'
    positions, species = [], []
    operations = _cif_operations(tags,loops,warnings)
    gram = lattice @ lattice.T
    metric_tolerance = max(1e-7,8*symprec*np.linalg.norm(lattice))
    if any(np.max(np.abs(r.T @ gram @ r-gram)) > metric_tolerance for r,_ in operations):
        raise ValueError('CIF symmetry rotations do not preserve the declared cell metric at this tolerance')
    def operation_key(r,t): return tuple(r.ravel())+tuple(np.round(_wrap(t),10))
    keys = {operation_key(r,t) for r,t in operations}
    if operation_key(np.eye(3,dtype=int),np.zeros(3)) not in keys:
        raise ValueError('CIF symmetry operations must include identity')
    for r,t in operations:
        for s,v in operations:
            rotation,translation=r@s,r@v+t
            if operation_key(rotation,translation) not in keys:
                bounds=symprec*np.linalg.norm(np.linalg.inv(lattice),axis=0)
                if not any(np.array_equal(rotation,candidate_r) and
                           _periodic_near(translation-candidate_t,lattice,symprec,bounds)
                           for candidate_r,candidate_t in operations):
                    raise ValueError('CIF symmetry operations are not a complete closed group')
    for row in rows:
        occupancy = _number(row.get('_atom_site_occupancy','1'))
        if abs(occupancy-1) > 1e-8: raise ValueError('Partial/zero occupancy is not an ordered crystal; provide an explicit ordered model')
        if any(row.get(key,'.') not in ('.','?','0') for key in ('_atom_site_disorder_group','_atom_site_disorder_assembly')):
            raise ValueError('Disordered CIF sites need an explicit ordered model')
        try: position = np.array([_number(row[prefix+s]) for s in 'xyz'])
        except KeyError as exc: raise ValueError('Incomplete CIF atom coordinates') from exc
        label = row.get('_atom_site_type_symbol')
        if not label:
            match = re.match(r'[A-Z][a-z]?',row.get('_atom_site_label',''))
            if not match: raise ValueError('CIF atom species missing')
            label = match.group(0)
        if cartesian: position = position @ np.linalg.inv(lattice)
        for rotation, translation in operations:
            positions.append(rotation @ position + translation); species.append(label)
            if len(positions) > 200000: raise ValueError('CIF symmetry expansion exceeds the 200000 candidate-site browser budget')
    positions,species = _deduplicate(positions,species,lattice,min(symprec,1e-5))
    if any(key.startswith('_atom_site_aniso') or key.startswith('_atom_site_u_') or key.startswith('_atom_site_b_') for key in all_keys):
        warnings.append('Thermal displacement metadata are retained in source CIF metadata; geometry exports omit displacement tensors.')
    return _validate_cell(lattice,positions,species,{'format':'cif','block':block['name'],'warnings':warnings,
                          'declared_symmetry_operation_count':len(operations),'source_site_rows':rows,'source_tags':tags})


def _orientation(number, lattice):
    """Cartesian S from upstream BC Table 3.1; independent of fractional U."""
    bravais = _BC_SETTINGS[number]['bravais']; s = np.eye(3)
    if bravais in ('MonoPrim','MonoBase'):
        cg = np.dot(lattice[0],lattice[2])/np.linalg.norm(lattice[0])/np.linalg.norm(lattice[2])
        sg = math.sqrt(max(0,1-cg*cg)); s = np.array([[sg,0,-cg],[-cg,0,-sg],[0,1,0]])
    elif bravais == 'TrigPrim': s = np.array([[-.5,math.sqrt(3)/2,0],[-math.sqrt(3)/2,-.5,0],[0,0,1]])
    elif bravais == 'HexaPrim': s = np.array([[0,1,0],[-1,0,0],[0,0,1]])
    if number in (17,19,28,29,31,33,36,46,53,61,70,122): s = np.array([[0,1,0],[-1,0,0],[0,0,1]]) @ s
    elif number in (38,39,40,41,57): s = np.array([[0,1,0],[0,0,1],[1,0,0]]) @ s
    elif number in (51,54): s = np.array([[0,0,-1],[0,1,0],[1,0,0]]) @ s
    elif number in (52,60): s = np.array([[1,0,0],[0,0,-1],[0,1,0]]) @ s
    return s


def _cell_result(lattice,positions,species,label):
    return {'label':label,'lattice':np.asarray(lattice).tolist(),'positions':_wrap(positions).tolist(),
            'species':list(species),'atom_count':len(species),'volume':float(abs(np.linalg.det(lattice)))}


def _bz_type(number,lattice):
    """Metric-dependent BC Brillouin-zone branch, from upstream get_BZ_type."""
    bravais=_BC_SETTINGS[number]['bravais']
    if bravais=='OrthBase': branch='a' if abs(2*lattice[0,0]) > abs(2*lattice[0,1]) else 'b'
    elif bravais=='OrthBody': branch='abc'[int(np.argmax(np.abs(2*lattice[0])))]
    elif bravais=='OrthFace':
        a,b,c=abs(2*lattice[0,0]),abs(2*lattice[1,1]),abs(2*lattice[0,2]);branch='a'
        if 1/c**2 > 1/a**2+1/b**2: branch='b'
        if 1/b**2 > 1/a**2+1/c**2: branch='c'
        if 1/a**2 > 1/c**2+1/b**2: branch='d'
    elif bravais=='TetrBody': branch='a' if abs(2*lattice[0,1]) > abs(2*lattice[0,2]) else 'b'
    elif bravais=='TrigPrim': branch='a' if abs(lattice[0,1]) > math.sqrt(2)*abs(lattice[0,2]) else 'b'
    else:return bravais
    return bravais+'('+branch+')'


def export_poscar(cell):
    species = list(dict.fromkeys(cell['species']))
    if any(re.search(r'\s',s) for s in species): raise ValueError('POSCAR species identifiers cannot contain whitespace')
    lines = [cell['label'],'1.0'] + [' '.join(f'{v:.15g}' for v in row) for row in cell['lattice']]
    lines += [' '.join(species),' '.join(str(cell['species'].count(s)) for s in species),'Direct']
    for s in species:
        lines += [' '.join(f'{v:.15g}' for v in row) for row,t in zip(cell['positions'],cell['species']) if t == s]
    return '\n'.join(lines)+'\n'


def export_cif(cell):
    lattice = np.asarray(cell['lattice']); lengths = np.linalg.norm(lattice,axis=1)
    angles = [math.degrees(math.acos(float(np.clip(np.dot(lattice[i],lattice[j])/lengths[i]/lengths[j],-1,1)))) for i,j in ((1,2),(0,2),(0,1))]
    lines = ['data_BC_cell','# Full explicit atom list; P1 metadata avoids a second symmetry expansion.']
    lines += ['_cell_length_'+s+' '+f'{v:.15g}' for s,v in zip('abc',lengths)]
    lines += ['_cell_angle_'+s+' '+f'{v:.15g}' for s,v in zip(('alpha','beta','gamma'),angles)]
    lines += ["_space_group_name_H-M_alt 'P 1'",'_space_group_IT_number 1','loop_','_space_group_symop_operation_xyz',"'x,y,z'",'loop_',
              '_atom_site_label','_atom_site_type_symbol','_atom_site_fract_x','_atom_site_fract_y','_atom_site_fract_z','_atom_site_occupancy']
    for i,(row,species) in enumerate(zip(cell['positions'],cell['species'])):
        if any(x in species for x in ('\n',"'",'"')): raise ValueError('CIF species label contains unsupported quote/newline')
        lines.append(f"site{i+1} '{species}' "+' '.join(f'{v:.15g}' for v in row)+' 1')
    return '\n'.join(lines)+'\n'


def _plain(value):
    if isinstance(value,np.ndarray): return value.tolist()
    if isinstance(value,np.generic): return value.item()
    if isinstance(value,dict): return {str(k):_plain(v) for k,v in value.items()}
    if isinstance(value,(tuple,list)): return [_plain(v) for v in value]
    return value


def run(payload, database=None):
    if not isinstance(payload,dict): raise ValueError('Structure input must be an object')
    symprec = float(payload.get('symprec',1e-5)); angle = float(payload.get('angle_tolerance',-1))
